//! Environment fragments generator and shell loader (/etc/profile.d/appdepot.sh and ~/.config/appdepot/env.sh).

use crate::Error;
use std::fs;
use std::path::{Path, PathBuf};

/// Generates a shell environment fragment for an application.
pub fn generate_fragment(app_id: &str, install_dir: &str) -> String {
    format!(
        "# Generated by AppDepot for {app_id}\nexport {var}_HOME=\"{dir}\"\nexport PATH=\"${var}_HOME/bin:$PATH\"\n",
        app_id = app_id,
        var = app_id.to_uppercase().replace('-', "_"),
        dir = install_dir
    )
}

/// Writes the user-scoped environment loader at ~/.config/appdepot/env.sh
/// and ensures it is cleanly sourced in ~/.bashrc without duplicates.
pub fn write_user_env_loader() -> Result<PathBuf, Error> {
    let home = std::env::var("HOME").map_err(|_| Error::Custom("HOME not set".into()))?;
    let config_dir = PathBuf::from(&home).join(".config/appdepot");
    let env_d = config_dir.join("env.d");
    fs::create_dir_all(&env_d)?;

    let env_sh = config_dir.join("env.sh");
    let content = r#"# AppDepot Environment Loader
# Ensures ~/.local/bin and AppDepot managed binaries are in PATH
case ":$PATH:" in
  *":$HOME/.local/bin:"*) ;;
  *) export PATH="$HOME/.local/bin:$PATH" ;;
esac

case ":$PATH:" in
  *":/opt/Application/bin:"*) ;;
  *) [ -d "/opt/Application/bin" ] && export PATH="/opt/Application/bin:$PATH" ;;
esac

if [ -d "$HOME/.config/appdepot/env.d" ]; then
  for frag in "$HOME/.config/appdepot/env.d"/*.sh; do
    [ -r "$frag" ] && . "$frag"
  done
fi
"#;

    fs::write(&env_sh, content.as_bytes())?;

    // Integrate with ~/.bashrc if not already present
    let bashrc = PathBuf::from(&home).join(".bashrc");
    if bashrc.exists() {
        if let Ok(existing) = fs::read_to_string(&bashrc) {
            let line =
                "[ -f \"$HOME/.config/appdepot/env.sh\" ] && . \"$HOME/.config/appdepot/env.sh\"";
            if !existing.contains(".config/appdepot/env.sh") {
                let updated = format!(
                    "{}\n\n# AppDepot Environment\n{}\n",
                    existing.trim_end(),
                    line
                );
                let _ = fs::write(&bashrc, updated);
            }
        }
    }

    Ok(env_sh)
}

/// Writes a per-application environment fragment into ~/.config/appdepot/env.d/<app_id>.sh
pub fn write_app_fragment(app_id: &str, install_dir: &Path) -> Result<PathBuf, Error> {
    let home = std::env::var("HOME").map_err(|_| Error::Custom("HOME not set".into()))?;
    let env_d = PathBuf::from(&home).join(".config/appdepot/env.d");
    fs::create_dir_all(&env_d)?;

    let fragment_file = env_d.join(format!("{}.sh", app_id));
    let content = generate_fragment(app_id, &install_dir.to_string_lossy());
    fs::write(&fragment_file, content.as_bytes())?;

    Ok(fragment_file)
}

/// Removes an application's environment fragment cleanly.
pub fn remove_app_fragment(app_id: &str) -> Result<(), Error> {
    let home = std::env::var("HOME").unwrap_or_default();
    let fragment_file = PathBuf::from(&home).join(format!(".config/appdepot/env.d/{}.sh", app_id));
    if fragment_file.exists() {
        let _ = fs::remove_file(fragment_file);
    }
    let sys_fragment = PathBuf::from(format!("/etc/profile.d/appdepot.d/{}.sh", app_id));
    if sys_fragment.exists() {
        let _ = fs::remove_file(sys_fragment);
    }
    Ok(())
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_generate_fragment() {
        let frag = generate_fragment("flutter-sdk", "/opt/Application/sdk/flutter");
        assert!(frag.contains("export FLUTTER_SDK_HOME=\"/opt/Application/sdk/flutter\""));
        assert!(frag.contains("export PATH=\"$FLUTTER_SDK_HOME/bin:$PATH\""));
    }
}
